) AS src(nk, mood, workload, satisf, cmt, cdate, week, emp)
LEFT JOIN sys.sys_users u ON u.user_external_code = 'LEGACY_EMP::'||src.emp
ON CONFLICT (pulse_check_tenant_id, pulse_check_natural_key) DO NOTHING;


DO $$
DECLARE n_surv int; n_q int; n_resp int; n_pulse int; resp_unresolved int; pulse_unresolved int;
BEGIN
  SELECT count(*) INTO n_surv  FROM sys.sys_surveys           WHERE survey_natural_key LIKE 'LEGACY_SURVEY::%';
  SELECT count(*) INTO n_q     FROM sys.sys_survey_questions  WHERE survey_question_natural_key LIKE 'LEGACY_SQ::%';
  SELECT count(*) INTO n_resp  FROM sys.sys_survey_responses  WHERE survey_response_natural_key LIKE 'LEGACY_SR::%';
  SELECT count(*) INTO n_pulse FROM sys.sys_pulse_checks      WHERE pulse_check_natural_key LIKE 'LEGACY_PC::%';
  SELECT count(*) INTO resp_unresolved  FROM sys.sys_survey_responses WHERE survey_response_subject_user_id IS NULL;
  SELECT count(*) INTO pulse_unresolved FROM sys.sys_pulse_checks    WHERE pulse_check_subject_user_id IS NULL;
  IF n_surv = 0 OR n_resp = 0 THEN
    RAISE EXCEPTION 'm2b import: empty surveys/responses (surveys=%, responses=%)', n_surv, n_resp;
  END IF;
  RAISE NOTICE 'm2b import: surveys=% questions=% responses=% (subj-unresolved %) pulse=% (subj-unresolved %)',
    n_surv, n_q, n_resp, resp_unresolved, n_pulse, pulse_unresolved;
END $$;

COMMIT;
